for date, rows in DAYS.items():
    items=[]
    for id,cat,t,s in rows:
        a=ALL[id]
        img=a['image']
        if not img or 'gnwcdn' in img or 'theverge' in img or 'ignimgs' in img:
            img=og(a['link']) or img
        items.append({"id":id,"category":cat,"source":a['source'],"title":a['title'],"title_fa":t,"summary_fa":s,
                      "link":a['link'],"image":img,"published":a['published']})
    now=datetime.now(timezone.utc).isoformat(timespec='seconds')
    d={"date":date,"updated_at":now,"fetched_at":now,"items":items}
    json.dump(d,open(f'/workspace/insta/days/{date}.json','w'),ensure_ascii=False,indent=1)
    print(date,[ (i['id'],bool(i['image'])) for i in items])
